def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            continue

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids only from previous_trace
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Base bid: aim to be competitive but not top-tier
    # If supply is tight, bid a bit more; if ample, bid less.
    tightness = 0.0
    if supply <= float(WATER_REQ):
        tightness = 1.0
    elif supply <= (float(MIN_SUPPLY) + float(WATER_REQ)) / 2.0:
        tightness = 0.6
    else:
        tightness = 0.3

    # Pressure from opponents: if someone previously bid very high, we raise slightly.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Threshold tuned from context: Bob died with ~138 max; others max ~145.
        if highest_prev_bid >= DAILY_SALARY * 1.7:  # ~119
            base = DAILY_SALARY * (0.55 + 0.15 * tightness)
        elif highest_prev_bid >= DAILY_SALARY * 1.4:  # ~98
            base = DAILY_SALARY * (0.50 + 0.12 * tightness)
        else:
            base = DAILY_SALARY * (0.45 + 0.10 * tightness)
    else:
        base = DAILY_SALARY * (0.45 + 0.10 * tightness)

    # React to our own hp/no-water streak
    if hp <= 2.0:
        base = DAILY_SALARY * 0.95
    elif hp <= 4.0:
        base = max(base, DAILY_SALARY * 0.75)

    if no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.70)

    # Safety clamp by budget and a reasonable cap to avoid dying like Bob
    # Keep under ~1.9*salary unless budget forces it.
    cap = min(budget, DAILY_SALARY * 1.9)
    bid = min(cap, base)

    # If budget is very low, spend what we can but avoid zero if possible
    if bid <= 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 110:
                    dangerous_prev.append(bid)

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, 55.0))
        return float(min(budget, 18.0))

    low_supply = supply <= 17
    mid_supply = supply <= 20
    late_game = day >= 8
    urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    base = 16.0

    if critical:
        if low_supply:
            base = 142.0
        elif mid_supply:
            base = 128.0
        else:
            base = 112.0
    elif urgent:
        if low_supply:
            base = 118.0
        elif mid_supply:
            base = 102.0
        else:
            base = 88.0
    else:
        if low_supply:
            base = 54.0
        elif mid_supply:
            base = 28.0
        else:
            base = 16.0

    if highest_prev >= 140:
        if urgent:
            base = max(base, 132.0 if low_supply else 116.0)
        else:
            base = min(base, 24.0)
    elif highest_prev >= 120:
        if urgent:
            base = max(base, 118.0 if mid_supply else 104.0)
        else:
            base = min(base, 22.0)
    elif highest_prev >= 90:
        if urgent:
            base = max(base, highest_prev + 2.0)
        else:
            base = max(base, 20.0 if low_supply else 16.0)
    else:
        if urgent:
            base = max(base, 72.0)
        else:
            base = max(base, 14.0)

    if avg_prev >= 115 and not urgent:
        base = min(base, 20.0)

    if late_game and budget > DAILY_SALARY * 3 and hp <= 4:
        base = max(base, 96.0)

    if budget < 35:
        base = min(base, budget)
    elif budget < 80 and not urgent:
        base = min(base, 24.0)

    if len(dangerous_prev) >= 2 and not urgent:
        base = min(base, 18.0 if not low_supply else 26.0)

    bid = max(0.0, min(budget, base))
    return float(round(bid, 2))
